ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["replies_ask_9"] = {
{"ASK_FOOD","role=rescue_medical|st=friendly,neutral",{"Sorry, I wish I had food, but we've been feeding patients first, and there's nothing left","I'd offer you broth if I had any, but the pot is empty..."}},
{"ASK_FOOD","role=rescue_medical|st=careful",{"Food? For you? No"}},
{"ASK_FOOD","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=19,21",{"Supper's on -- such as it is"},false,false,{[1]={{t="there's not much to share",afterMs=3500}}}},
{"ASK_FOOD","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=5,10",{"Breakfast was a biscuit..."},false,false,{[1]={{t="I ate it",afterMs=3500},{t="sorry",afterMs=3000}}}},
{"ASK_FOOD","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=11,18",{"Lunch is a can of beans"},false,false,{[1]={{t="and I'm eating slow",afterMs=3500}}}},
{"ASK_FOOD","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=22,4",{"At this hour?"},false,false,{[1]={{t="I've got a crust of bread and a prayer",afterMs=3500}}}},
{"ASK_FOOD","reg=civilian,family,worker,rescue|st=careful",{"No, there's no food, and even if there was, why would I tell you","I don't have any!!","Ask someone who gives a damn","Do I look like a pantry?"},false,false,{[2]={{t="and if I did, I wouldn't tell you",afterMs=3000}}}},
{"ASK_FOOD","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Food? Oh God, I wish, I wish I had some to spare, we're down to crackers","I'm sorry, I'm so sorry, we're hungry too, we've got two cans and four mouths","Hungry? Me too... my stomach's eating itself!!","I wish I could, I really do","Hardly anything- some dried beans, a heel of bread!!","Food's the one thing I can't give away, I can't, I'm sorry!","Oh... honey, we've been rationing for days","No, but I know how you feel","I'd share if I could, I would"},false,false,{[3]={{t="I'm sorry, I have nothing",afterMs=3200}},[4]={{t="the kids come first, and there's barely enough for them",afterMs=3500}},[5]={{t="I can't share it, I'm sorry",afterMs=3200}},[8]={{t="my belly's been growling since Tuesday",afterMs=3500}},[9]={{t="ask me again when I've got more than I need",afterMs=3200}}}},
{"ASK_FOOD","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Food's gold, and I've got none to spare","Everything I have is accounted for","Sorry, friend, no","I can tell you where I found some, but I can't hand it over","Hungry all the time now, I don't notice it anymore","We're on thirds","You'll have to forage, friend, I can't help","If I had a surplus, I'd give you half"},false,false,{[2]={{t="sorry",afterMs=3500}},[3]={{t="try the farms, the gardens, the cellars",afterMs=3200}},[5]={{t="I'm hungry too",afterMs=3500}},[6]={{t="a third of a can, three times a day",afterMs=3200}},[8]={{t="I don't",afterMs=3500}}}},
{"ASK_FOOD","reg=civilian,family,worker,rescue|st=friendly",{"For you, I'd give anything, but I'm empty-handed, truly","I wish I could feed you"},false,false,{[1]={{t="come back when I've got something!",afterMs=3200}},[2]={{t="you've done so much for us",afterMs=3500}}}},
{"ASK_FOOD","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"Food? I've got half a stick of gum and a lot of attitude","I'm saving my last can for a special occasion"},false,false,{[2]={{t="the occasion is \"tomorrow\"",afterMs=3200}}}},
{"ASK_FOOD","reg=raider|st=hostile",{"Food? I'll feed you a knuckle sandwich!","You want food? Starve, like everybody else!","Beg somewhere else, I'm not your mother!","Food's for people who earn it, and you haven't!","You hungry? Good, hunger makes you quick, or dead!"}},
{"ASK_FOOD","reg=gang|st=hostile",{"Food? Get your own, I ain't a restaurant!","You want to eat? Eat dirt!","My people eat first, and you ain't one of them!","Don't ask me for nothing, understand?"}},
{"ASK_FOOD","reg=club|st=hostile",{"Food? Shut your mouth and walk away","I don't share, not with you","Go beg somewhere else, {g:brother|sister}","Pig roast was last Saturday, you missed it, and you weren't invited"}},
{"ASK_FOOD","reg=crime|st=hostile",{"I do not feed those who threaten me","Food is for friends, and you're not one"}},
{"ASK_FOOD","reg=prison|st=hostile",{"I've got nothing, leave me alone!","Don't ask me for food, I'll kill you for it!"}},
{"ASK_FOOD","reg=outlaw|st=hostile",{"Find your own, I'm not sharing","Food? Keep walking, stranger"}},
{"ASK_FOOD","reg=law|st=hostile",{"No food for hostile persons, move along"}},
{"ASK_FOOD","role=militia|st=hostile",{"We don't feed strangers who point guns at us"}},
{"ASK_FOOD","st=hostile",{"Nothing to spare - fuck off, we're all dead anyways","You think I'm carrying a grocery store? Get away from my bag","Ask me for food again and see what happens","Do I look like the lunch line? Keep walking"}},
{"ASK_FOOD","tmp=predator|st=hostile",{"For you? Hah - no"}},
{"ASK_FOOD","st=hostile,careful",{"Your stomach isn't my responsibility - move along"}},
{"ASK_FOOD","st=careful",{"Not for somebody walking up and counting what I might have","Don't come any closer to ask that, the answer's no from there too","I heard you the first time, I don't have anything I'm giving away","First thing you wanna know is what I'm carrying? No - keep moving","Do you want the polite answer?"},false,false,{[5]={{t="Forget I said that, being an ass",afterMs=2000},{t="Can't spare food - sorry",afterMs=2400}}}},
{"ASK_FOOD","tmp=fresh|st=friendly,neutral",{"Please don't look at me like that, I can't spare anything"}},
{"ASK_FOOD","tmp=fresh|st=friendly",{"Oh... don't make me say no, I have to, but... I'm sorry","We're asking strangers for food now - fuck - sorry, no, I can't help either","Sure, I can just--","I can't - please don't ask me again"},false,false,{[3]={{t="No, no, sorry - wasn't thinking",afterMs=1800},{t="Can't give you any food, sorry I said that",afterMs=3000}},[4]={{t="I'm not angry, I'm--",afterMs=2400},{t="Gonna start crying - please, just talk about something else",afterMs=3500}}}},
{"ASK_FOOD","st=friendly,neutral",{"I keep saying I'll help people, can't even do half of what I promised - sorry, no food","Can't share any today - sorry, wish I could","I know about ten ways to cook beans - don't have any beans to give you, though - not much use, am I?","No spare food, you can still stop and talk, though - I didn't mean get lost","No, sorry, keep saying sorry like that's gonna help, don't I?","Nothing I can give you, hate saying it","Can't feed you, shitty answer, I know","I don't have a meal for you, I used to hate throwing out leftovers, wish I'd hated it more","No spare food here - don't follow a stranger into a back room just because they say they've got some","No, sorry if that sounded mean, I can't spare any, that's all","Food? Hang on...","Have you tried..."},false,{[3]="GENERIC",[5]="GENERIC"},{[11]={{t="Nah - don't know why I said hang on",afterMs=3000},{t="Can't spare any - sorry",afterMs=2200}},[12]={{t="No, you've probably tried everything I can think of",afterMs=2400},{t="Can't feed you - I'm sorry, I'll shut up",afterMs=3000}}}},
{"ASK_FOOD","st=friendly",{"I'm sorry you're hungry - I can't... I just can't spare anything","Not from me, I'm sorry - try somebody else, okay? Somebody's got to have more than me","I really wanna say yes","No spare food - sorry"},false,false,{[3]={{t="Can't, though",afterMs=3000},{t="I'm sorry, I know you're hungry",afterMs=1800}},[4]={{t="Wait, I didn't mean you had to leave",afterMs=3000},{t="You can still tell me how you're doing",afterMs=3000}}}},
{"ASK_FOOD","st=neutral,careful",{"No food for you, and give people some room when you ask, makes 'em nervous","Food is..."},false,false,{[2]={{t="You know what, you know how rationing works - don't need me explaining it",afterMs=2300},{t="Nothing spare - sorry",afterMs=2800}}}},
{"ASK_FOOD","reg=military,law|st=neutral,friendly,careful",{"No rations to hand out, uniform doesn't mean I've got supplies for you"}},
{"ASK_FOOD","reg=military|st=neutral,careful",{"Negative, no spare meals, this isn't a supply point"}},
{"ASK_FOOD","reg=law|st=friendly,neutral",{"Can't help you with food, if somebody else offers, ask what they want first - be careful"}},
{"ASK_FOOD","reg=family|st=friendly",{"I used to get everybody fed before I sat down - now I can't even--... Sorry, nothing I can spare","Nearly asked you over for supper then"},false,false,{[2]={{t="Wash your hands, sit down, I'll put something on...",afterMs=3000},{t="Can't, though, got nothing to offer you",afterMs=4000}}}},
{"ASK_FOOD","reg=family|st=friendly,neutral",{"I'd normally ask if you'd eaten, got nothing to put on for you, though"}},
{"ASK_FOOD","role=rescue_clergy|st=friendly",{"I can't spare food, and no, you don't need a sermon from me either","I can't give you a meal"},false,false,{[2]={{t="Could pray with you, but I... that's not what you asked for",afterMs=3000},{t="I'm sorry - really am",afterMs=3000}}}},
{"ASK_FOOD","reg=rescue|st=friendly",{"Sorry, nothing I can give you to eat, I wish I had a better answer"}},
{"ASK_FOOD","reg=club,outlaw,crime|st=neutral,careful",{"I'm keeping my supplies - don't start, all right?"},false,{[1]="GENERIC"}},
{"ASK_FOOD","reg=outlaw,prison|st=careful",{"No handouts, don't wanna hear what you'll do for it either"}},
{"ASK_FOOD","st=friendly,neutral|day=14,3650",{"Can't help, used to get asked what I WANTED for dinner - remember that?"},false,{[1]="GENERIC"}},
{"ASK_FOOD","role=family_elder|st=friendly",{"My dear... uhhh--","Sweetheart, I..."},false,false,{[1]={{t="I mean...",afterMs=3000},{t="No, I'm sorry, can't spare food, wish you hadn't had to ask me",afterMs=3000}},[2]={{t="Sorry, keep calling everybody that",afterMs=2200},{t="I haven't got a meal for you, wish I did, sweetheart - oh, there I go again",afterMs=3000}}}},
{"ASK_FOOD","tmp=fresh|st=neutral",{"No, just no"},false,false,{[1]={{t="Hey, sorry, didn't mean to snap",afterMs=2000},{t="You can ask, I just can't share any",afterMs=2800}}}},
{"ASK_FOOD","reg=family|st=neutral",{"I can't feed another mouth"},false,false,{[1]={{t="Person - fuck, sorry",afterMs=1800},{t="I'm just tired, didn't mean it like that",afterMs=2500}}}},
{"ASK_FOOD","role=soldier_green|st=neutral,friendly",{"No ration for you"},false,false,{[1]={{t="Uh, that wasn't an order - sorry",afterMs=2000},{t="I mean I haven't got one to give you",afterMs=2500}}}},
{"ASK_FOOD","reg=civilian,worker|st=neutral|world=building",{"I'm not running a soup kitchen"},false,false,{[1]={{t="Ah, fuck - sorry",afterMs=2000},{t="You only asked, can't spare anything, that's all",afterMs=2800}}}},
{"ASK_FOOD","reg=civilian,rescue|st=friendly",{"Always kept crackers in my desk"},false,false,{[1]={{t="Somebody hadn't eaten, I'd just... open the drawer",afterMs=2400},{t="Don't have any now - sorry, I'm going on",afterMs=3500}}}},
{"ASK_FOOD","reg=family,civilian|st=friendly",{"My mom used to keep so much in her pantry..."},false,false,{[1]={{t="Listen to me, that's not gonna feed you, is it",afterMs=3000},{t="I haven't got anything to give you - sorry",afterMs=2400}}}},
{"ASK_FOOD","reg=worker,civilian|st=friendly",{"Wish you'd caught me before all this"},false,false,{[1]={{t="Would've taken you to lunch, any excuse to get out of work, heh",afterMs=2600},{t="Can't offer food now, though",afterMs=3500}}}},
{"ASK_FOOD","reg=club,crime|st=careful",{"No, the answer is no"},false,false,{[1]={{t="I'm not gonna hit you for asking - Jesus",afterMs=2000},{t="Just not sharing - leave it there",afterMs=2600}}}},
{"ASK_FOOD","reg=family|tmp=fresh|st=friendly",{"We've got a sleeve of saltines and a jar of peanut butter - take a couple, just don't let the kids see me handing it out"}},
{"ASK_FOOD","reg=civilian|tmp=fresh|st=friendly",{"I got one can of Vienna sausages left, I was saving it, but you look worse off than me - split it?"},false,{[1]="SHARE_FOOD"}},
{"ASK_FOOD","reg=civilian|tmp=fresh|st=neutral",{"Food? I've been eating dry cereal out of the box since Tuesday - I'm sorry, I really am"}},
{"ASK_FOOD","reg=civilian,family|tmp=fresh|st=friendly|world=vehicle",{"My mama put up green beans last fall, there's four jars in the car - you want to sit and eat one with me?"},false,{[1]="SHARE_FOOD"}},
{"ASK_FOOD","reg=family|tmp=fresh|st=neutral,careful",{"My boys haven't had a hot meal since the power quit - I can't give away what's theirs, I'm sorry, okay?"},false,{[1]="GENERIC"}},
{"ASK_FOOD","reg=civilian,family|tmp=fresh|st=careful|hour=16,5",{"Please don't come closer, we barely have enough for tonight - please just go, okay?"},false,{[1]="GENERIC"}},
{"ASK_FOOD","reg=civilian,family|tmp=fresh|st=hostile",{"Don't you touch our food, I'll yell, I swear I will, and they'll come for both of us"}},
{"ASK_FOOD","reg=family|role=family_elder|st=friendly,neutral",{"There's a garden behind the Baptist church in Riverside, pole beans are coming in and nobody's picking 'em"}},
{"ASK_FOOD","reg=family|role=family_elder|st=friendly",{"I raised six kids on less than this, here's a biscuit - it's hard as a brick, soak it in something"}},
{"ASK_FOOD","reg=civilian|tmp=seasoned|st=neutral",{"I can spare one can of corn - one - don't make it a habit"}},
{"ASK_FOOD","reg=civilian|tmp=seasoned|st=neutral,careful",{"Everybody asks me that, the houses on {street} ain't all been picked yet, start at the blue one"}},
{"ASK_FOOD","reg=civilian|tmp=seasoned|st=careful,hostile",{"I don't feed strangers, the last one I fed came back with friends"}},
{"ASK_FOOD","reg=worker|st=friendly,neutral",{"Half a bologna sandwich in my lunch pail, it's been in there since the ninth - I wouldn't"}},
{"ASK_FOOD","reg=worker|st=neutral",{"The Army dropped pallets of rations at the high school the first week - somebody might have missed a box"}},
{"ASK_FOOD","reg=worker|st=friendly",{"Break room vending machine at the plant still has chips in it - you'll need a pry bar and a good excuse"}},
{"ASK_FOOD","reg=worker|st=careful,hostile",{"Get your own, I worked a double for every can in this bag"}},
{"ASK_FOOD","reg=rescue|role=rescue_medical|st=friendly,neutral",{"When did you last eat? Sit down before you fall down - here, a granola bar, chew it slow"}},
{"ASK_FOOD","reg=rescue|role=rescue_clergy|st=friendly,neutral",{"The Lord provides, lately He's been providing mostly creamed corn, but you're welcome to it"}},
{"ASK_FOOD","reg=rescue|role=rescue_firefighter|st=friendly|world=building",{"Station pantry had chili and coffee, we're down to the coffee - want a cup and the last of the crackers?"},false,{[1]="SHARE_FOOD"}},
{"ASK_FOOD","reg=rescue|st=careful",{"I can't hand out food to anybody who won't keep their distance - back up and we'll see"}},
{"ASK_FOOD","reg=law|tmp=seasoned|st=friendly,neutral",{"We keep emergency rations for folks in real trouble - you walking and talking? Then I can give you one bar, {sir}"}},
{"ASK_FOOD","reg=law|st=careful",{"Hands where I can see them first, then we talk about food"}},
{"ASK_FOOD","reg=law,swat|st=hostile|world=building",{"This unit isn't a soup kitchen - step back and keep walking"}},
{"ASK_FOOD","reg=law|tmp=veteran|st=neutral",{"There's a Red Cross cot line at the Muldraugh elementary - was, anyway, I'd try there before you try me"}},
{"ASK_FOOD","reg=law|tmp=veteran|st=friendly|world=vehicle",{"Got a pack of peanut butter crackers in the cruiser - here, you didn't get it from the county"}},
{"ASK_FOOD","reg=swat|st=neutral,careful",{"Negative on food, team's on short rations as it is - keep moving, {sir}"}},
{"ASK_FOOD","reg=military|tmp=fresh|st=friendly,neutral",{"Uh, Sergeant says rations stay counted, but, okay, here, you didn't get this from me"}},
{"ASK_FOOD","reg=military|tmp=seasoned|st=neutral",{"Rations are counted at the checkpoint, aid station's by the water tower if it's still standing"}},
{"ASK_FOOD","reg=military|tmp=veteran|st=friendly",{"One MRE, chili and macaroni, the heater pouch is not food - people keep asking"}},
{"ASK_FOOD","reg=military|st=careful,hostile",{"You're not getting Army chow by walking up on a patrol - back off, now"}},
{"ASK_FOOD","reg=elite|st=neutral,careful,hostile",{"Negative - keep moving"}},
{"ASK_FOOD","reg=elite|st=friendly",{"Grain elevator east of town, rats found it first, but there's plenty"}},
{"ASK_FOOD","reg=outlaw|st=neutral",{"Food costs, friend - what've you got?"},false,{[1]="TRADE_OFFER"}},
{"ASK_FOOD","reg=outlaw|st=careful,hostile",{"I eat, you watch, that's how it's going today"}},
{"ASK_FOOD","reg=raider|tmp=predator|st=hostile,careful",{"Hungry? Aw - drop the bag and maybe I'll let you lick the can when I'm done"}},
{"ASK_FOOD","reg=raider|st=neutral",{"Sure we got food, got it off folks who asked real nice, same as you"}},
{"ASK_FOOD","reg=raider,prison|tmp=predator|st=neutral,hostile",{"You want some beef jerky? Say please - go on, say it"},false,{[1]="SHARE_FOOD"}},
{"ASK_FOOD","reg=gang|st=hostile,careful",{"Walking on our block asking for groceries - that's cute, that's real cute"}},
{"ASK_FOOD","reg=gang|st=neutral",{"Corner store's ours now, you want a honey bun, you pay what the man says"}},
{"ASK_FOOD","reg=club|st=neutral,careful",{"The club feeds its own, you ain't wearing a patch"}},
{"ASK_FOOD","reg=crime|st=neutral,friendly",{"Everything has a price, beans are one shell a can, and that is a friendly price"}},
{"ASK_FOOD","reg=prison|st=hostile,careful",{"They fed me through a slot for six years, now I eat first - ask me again and see what happens"}},
{"ASK_FOOD","reg=prison|st=neutral|world=window",{"Food? Man, I ate a whole pie off a windowsill on the ninth - best day of my life, you're too late"}},
{"ASK_FORT_KNOX","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=friendly,neutral",{"Everybody says it's safe up there, but nobody's come back to tell us"}},
{"ASK_FORT_KNOX","role=family_elder|tmp=seasoned|st=friendly,neutral",{"Lot of gold in that place once, now it's a lot of rumors"}},
{"ASK_FORT_KNOX","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral|world=building",{"Heard it's a fortress with soldiers, walls and food, maybe it's true"}},
{"ASK_FORT_KNOX","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral",{"Radio said they were taking refugees in up there, ain't heard it in a while"}},
{"ASK_FORT_KNOX","role=civilian_loner|tmp=seasoned|st=friendly,neutral|world=fence",{"Too many guns, too many fences - not going near it"}},
{"ASK_FORT_KNOX","role=worker|tmp=seasoned|st=friendly,neutral|world=vehicle,cars,road",{"Truck drivers say the road to Knox is a parking lot of abandoned cars"}},
{"ASK_FORT_KNOX","role=rescue_firefighter|tmp=seasoned|st=friendly,neutral",{"Our company got a call to help, we never made it"}},
{"ASK_FORT_KNOX","role=rescue_medical|tmp=seasoned|st=friendly,neutral",{"Heard they're taking doctors - I'm tempted, but my patients are here"}},
{"ASK_FORT_KNOX","role=rescue_clergy|tmp=seasoned|st=friendly,neutral",{"A place of power, whether it's of good or evil, I can't say"}},
{"ASK_FORT_KNOX","role=law_deputy,law_officer|tmp=seasoned|st=friendly,neutral",{"Last bulletin said there was an evacuation point, that was days ago"}},
{"ASK_FORT_KNOX","role=law_sheriff,law_sergeant|tmp=veteran|st=friendly,neutral",{"Heard it's closed, heard it's open, heard it's a trap - pick one"}},
{"ASK_FORT_KNOX","role=law_trooper|tmp=veteran|st=friendly,neutral|world=road",{"Road to Knox is blocked at the county line, I turned around"}},
{"ASK_FORT_KNOX","role=law_corrections|tmp=seasoned|st=friendly,neutral",{"Don't trust a fort that doesn't answer its radio"}},
{"ASK_FORT_KNOX","role=swat_lead,swat_operator|tmp=veteran|st=friendly,neutral",{"Not our area"}},
{"ASK_FORT_KNOX","role=soldier,soldier_green|tmp=seasoned,fresh|st=friendly,neutral",{"I'm not allowed to talk about it"}},
{"ASK_FORT_KNOX","role=soldier_nco|tmp=veteran|st=friendly,neutral|world=building",{"It's a big base with a lot of walls, whether it still has anyone inside, I couldn't tell you"}},
{"ASK_FORT_KNOX","role=deserter,militia|tmp=seasoned|st=friendly,neutral",{"Fort Knox is where the Army hides when it's afraid - I left before I found out"}},
{"ASK_FORT_KNOX","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=friendly,neutral",{"Heavily fortified - that's all"}},
{"ASK_FORT_KNOX","role=outlaw|tmp=seasoned|st=friendly,neutral",{"Heard guards shoot anybody who comes close, not my kind of place"}},
{"ASK_FORT_KNOX","role=raider,raider_boss|tmp=predator|st=friendly,neutral",{"A fortress full of food and weapons? Sounds like a fine target"}},
{"ASK_FORT_KNOX","role=gang_member,gang_boss|tmp=predator|st=friendly,neutral",{"Soldiers won't let us in, we wouldn't let them out - even"}},
{"ASK_FORT_KNOX","role=biker,biker_boss|tmp=predator,veteran|st=friendly,neutral",{"Rode by the perimeter, looked cold and empty - smelled worse"}},
{"ASK_FORT_KNOX","role=crime_member|tmp=seasoned|st=friendly,neutral",{"There's a whole economy up there, if you know the right people"}},
{"ASK_FORT_KNOX","role=prisoner|tmp=predator|st=friendly,neutral",{"Where the government keeps its toys - stay away"}},
{"ASK_FORT_KNOX","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral",{"Fort Knox? the gold place? they said it's sealed, locked down, nobody gets in or out","I tried to go there, I got to the main gate and there's soldiers, hundreds, and they're pointing guns outward","It's ten minutes away and I can't get near it, and I keep thinking that's where the help is","My uncle worked in the PX, he's inside, if he's alive, that's where he'd be","Rumor is they've got generators, food, medicine, the works, and not a single soldier will tell us how to get in","Everyone's headed there, everyone, and the line is a mile long, and nobody moves"}},
{"ASK_FORT_KNOX","role=civilian_man,civilian_woman|tmp=seasoned|st=friendly,neutral",{"Closed to civilians, last I heard, they shot a few people who walked up, so, I don't go near","It's a fortress... been one for a hundred years, so I figure it's got a fighting chance","They're hunkered down, I imagine, waiting out the end of the world, same as us, but with better rations","Some say the gold is still there, but who cares about gold, give me a hot meal","Armored vehicles at the gates, and the gates don't open, that's the last news, and that's all I know"}},
{"ASK_FORT_KNOX","role=civilian_man,civilian_woman|st=friendly",{"Wish I could tell you more, if I hear anything, you'll be the first to know","Only that it's still standing, as far as I know, and that gives me a little hope"}},
{"ASK_FORT_KNOX","role=civilian_man,civilian_woman|st=careful",{"Why? are you planning something?","Stay away from there -- it's none of your concern"}},
{"ASK_FORT_KNOX","role=civilian_loner",{"Place has been locked down since the second day, I've watched it from the ridge, not a soul comes out","Everybody thinks Fort Knox is a miracle, it's just a base, with walls and men who are as scared as us","Heard they let a few families in, then closed the gate, heard they let nobody in, who knows","I'd stay away, the army shoots first, and apologizes never"}},
{"ASK_FORT_KNOX","role=family_man,family_woman,family_elder,family_youth|st=friendly,neutral",{"We drove up to the gate on the first day, and a soldier told us to turn around, said the base was full","My cousin's husband is stationed there, we haven't heard a thing, the not knowing is worse"}},
{"ASK_FORT_KNOX","role=family_elder",{"My late husband was stationed at Knox in '53, honey, I never thought I'd see it from the other side of a gate","They keep gold there, they say, but I've never seen it, and I'd trade it all for one hot meal"}},
{"ASK_FORT_KNOX","role=family_youth",{"We learned about it in school, Fort Knox, gold, I thought it was a joke, but it's real, it's, like, a fortress","My friend's dad works there, and he hasn't come home, I've asked at the gate, they won't tell me anything"}},
{"ASK_FORT_KNOX","role=worker",{"Convoy left from the base on the sixth, headed north, never came back, I saw 'em roll out, and I got a bad feeling","Tanks, trucks, jeeps, they got everything in there, they could come get us all if they wanted"}},
{"ASK_FORT_KNOX","role=rescue_medical",{"They sent a doctor out to look at some of our patients, then called him back, and that was that","The base hospital is the best in the state, and I'd give anything to be inside it"}},
{"ASK_FORT_KNOX","role=rescue_clergy",{"There's a chaplain there, I know him, I wrote him a letter, and I haven't had a reply","God willing, they're praying, too"}},
{"ASK_FORT_KNOX","role=rescue_firefighter",{"The base fire department asked for mutual aid, then radio silence, I lost three friends there"}},
{"ASK_FORT_KNOX","role=militia",{"They sealed it up on the sixth and nothing's moved since, no flags, no signals, no helicopters","I wouldn't try the main gate, if you must go, use the creek bed on the west side, but I never told you that"}},
{"ASK_FORT_KNOX","reg=civilian,family,worker,rescue|st=friendly,neutral",{"Everybody wants in","They say the gold is still there","I tried the gate on the second day","My brother-in-law worked there","I heard it's a fortress","Folks line up at the gate","They say they let kids in","I can see the lights from the ridge","It's the safest place in the county, or the most dangerous","The dogs bark up there","They won't take anyone with a bite"},false,false,{[1]={{t="nobody gets in",afterMs=3200}},[2]={{t="nobody cares about gold now",afterMs=3500}},[3]={{t="a soldier pointed his rifle at my chest",afterMs=3500},{t="I turned around",afterMs=3000}},[4]={{t="I haven't heard from him",afterMs=3200},{t="I'm not going to",afterMs=3000}},[5]={{t="fences, towers, searchlights",afterMs=3500},{t="I hope it holds",afterMs=3000}},[6]={{t="some give up and go home",afterMs=3200},{t="some don't go home",afterMs=2800}},[7]={{t="and nobody else",afterMs=3500},{t="I'd send mine, if I had any",afterMs=3000}},[8]={{t="on a clear night",afterMs=3500},{t="I think about them",afterMs=3000}},[9]={{t="nobody agrees",afterMs=3200}},[10]={{t="from miles away",afterMs=3500},{t="I think they're searching",afterMs=3000}},[11]={{t="and they check",afterMs=3200},{t="thoroughly",afterMs=2800}}}},
{"ASK_FORT_KNOX","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"All that gold, and no one can buy a sandwich with it","Fort Knox has the gold, and we have the sandwiches","All that gold"},false,false,{[1]={{t="the joke writes itself",afterMs=3200}},[2]={{t="I'd say we're ahead",afterMs=3000}},[3]={{t="and not one of us can buy a biscuit",afterMs=3200}}}},
{"ASK_FORT_KNOX","reg=civilian,family,worker,rescue|st=friendly",{"I'd love to see it again someday"},false,false,{[1]={{t="I took my kids on a field trip once",afterMs=3200}}}},
{"ASK_FORT_KNOX","reg=civilian,family,worker,rescue|st=careful",{"Fort Knox? Why do you want to go there?","Stay AWAY from the base","You asking about the base for a reason? You a soldier? A deserter? Keep your hands out"}},
{"ASK_FORT_KNOX","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=fear",{"Don't go near the base, they shoot, they SHOOT"}},
{"ASK_FORT_KNOX","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=sad",{"My brother went in"},false,false,{[1]={{t="never came out",afterMs=3500}}}},
{"ASK_FORT_KNOX","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=angry",{"They sealed the gold and left the people, think about that"}},
{"ASK_FORT_KNOX","reg=civilian,family,worker,rescue|st=friendly|mood=warm",{"It was beautiful once, ha"},false,false,{[1]={{t="my dad took me to the museum",afterMs=3200}}}},
{"ASK_FORT_KNOX","reg=raider|st=neutral,careful",{"Fort Knox? They've got the gold, the guns, and all the tanks, and they're sitting on their hands","Gold vault's right there, everybody knows it, I'd love to see what's left of it","They locked the gates, shot at anybody who tried to get in, that's what a guy told me","Whole base is on lockdown, lights out, no one answering the phone, I don't know what that means","The Army's in there, safe and sound, while we're out here getting eaten"}},
{"ASK_FORT_KNOX","reg=raider|st=hostile",{"Fort Knox is none of your concern, you try going there and see what happens"}},
{"ASK_FORT_KNOX","reg=raider|st=friendly",{"I tried to get in, they wouldn't open the gate, I begged, on my mother I begged"}},
{"ASK_FORT_KNOX","reg=gang|st=neutral,careful",{"Fort Knox, {g:man|lady}, everyone knows the Army's holed up there, with the gold","My cousin was stationed there, ain't heard a thing","Big tanks, big guns, big nothing, they ain't helping us","Heard some soldiers got out, turned, and came back, that's what messed up the base"}},
{"ASK_FORT_KNOX","reg=gang|st=hostile",{"Fort Knox is a death trap, so stay away"}},
{"ASK_FORT_KNOX","reg=gang|st=friendly",{"I hope they get their act together and help us"}},
{"ASK_FORT_KNOX","reg=club|st=neutral,careful",{"Fort Knox, hell, I rode past it Saturday, fences up, soldiers on top, didn't wave","The whole base is sealed, dogs patrolling, I'm not going near it","Most of the guys I served with are in there, I wonder who's alive"}},
{"ASK_FORT_KNOX","reg=club|st=hostile",{"Don't talk about the base around me"}},
{"ASK_FORT_KNOX","reg=club|st=friendly",{"I hope the gate opens soon, {g:brother|sister}"}},
{"ASK_FORT_KNOX","reg=crime|st=neutral,careful",{"Fort Knox holds the gold reserve, which the government will protect before the people","The base is a fortress, and it's keeping the rest of us out","Rumor says they have a vaccine locked inside, and I believe it, because they'd never share it"}},
{"ASK_FORT_KNOX","reg=crime|st=friendly",{"It would be a helpful thing if they opened the doors"}},
{"ASK_FORT_KNOX","reg=prison|st=neutral,careful",{"Fort Knox? They'd shoot me on sight, I'm staying away","Soldiers there don't care who you are, convict or not"}},
{"ASK_FORT_KNOX","reg=prison|st=friendly",{"Maybe they'd take me in, if I begged"}},
{"ASK_FORT_KNOX","reg=outlaw|st=neutral,careful",{"Fort Knox has been quiet for days, no activity, no lights","I heard gunfire from there on the second night, then nothing","Soldiers deserted the base, some of them anyway, I met a few"}},
{"ASK_FORT_KNOX","reg=outlaw|st=friendly",{"If you can get through the fence, they might help, but I wouldn't count on it"}},
{"ASK_FORT_KNOX","role=deserter|st=neutral,careful",{"I was stationed there, I'm not going back, I can't"}},
{"ASK_FORT_KNOX","role=deserter|st=hostile",{"Don't ask me about the base!! DON'T!!"}},
{"ASK_FORT_KNOX","reg=law|st=neutral,careful",{"Fort Knox command is not responding to our requests for assistance","We've been told the base is secure, nothing else","I sent a deputy to the gate, he was turned away at gunpoint"}},
{"ASK_FORT_KNOX","reg=law|st=hostile",{"Do not approach the base, they have orders to shoot"}},
{"ASK_FORT_KNOX","reg=law|st=friendly",{"If they'd open the gates, we could save so many more people"}},
{"ASK_FORT_KNOX","role=law_sheriff|st=neutral,careful",{"I've asked Fort Knox for help a dozen times, and I'm still waiting"}},
{"ASK_FORT_KNOX","reg=military|st=neutral,careful",{"The installation is secure","Fort Knox is operating under quarantine protocols","That's all I'm authorized to say"}},
{"ASK_FORT_KNOX","reg=military|st=hostile",{"Fort Knox is off limits to civilians, do not approach"}},
{"ASK_FORT_KNOX","reg=military|st=friendly",{"It's a rough situation everywhere, ours included, but the base is holding"}},
{"ASK_FORT_KNOX","role=soldier_nco|st=neutral,careful",{"The base is the last line, we hold it or the county falls"}},
{"ASK_FORT_KNOX","role=soldier_green|st=neutral,careful",{"I was supposed to be at Knox... I'm lost, I think, nobody's told me where to go"}},
{"ASK_FORT_KNOX","reg=elite|st=neutral,careful",{"Fort Knox is a topic you should drop"}},
{"ASK_FORT_KNOX","role=mercenary|st=neutral,careful",{"There's more at Knox than just soldiers, believe me"}},
{"ASK_FORT_KNOX","role=militia|st=neutral,careful",{"We tried to get help at Knox, they turned us away, said they had orders","Smoke over the base for two days, then it cleared, now it's quiet, too quiet"}},
{"ASK_FORT_KNOX","role=militia|st=friendly",{"If they open the gates, we'll be the first in line, I'll tell you that"}},
{"ASK_FORT_KNOX","reg=civilian,family|tmp=fresh|st=friendly,neutral|day=0,9",{"They've got tanks up there, and all that gold, if anybody makes it, it's them - right?"},false,{[1]="GENERIC"}},
{"ASK_FORT_KNOX","reg=family|tmp=fresh|st=friendly,neutral|sex=f",{"My husband cooks on post, he called Friday night and said he couldn't come home yet - he's still up there, he's just not answering"}},
{"ASK_FORT_KNOX","reg=civilian,family|tmp=fresh|st=friendly,neutral",{"I tried the gate - MP said civilians go home, I said I don't have one anymore - he said I'm sorry, {sir}, go home"}},
{"ASK_FORT_KNOX","reg=civilian,family|tmp=fresh|st=friendly,neutral|world=building",{"All my life I thought, if something bad ever happens, at least we live next door to the Army"}},
{"ASK_FORT_KNOX","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral",{"All that gold up there and not one bar of it buys a phone line that works","Base is up, or something's up there, lights at night, guns in the day, they're not sharing either one"}},
{"ASK_FORT_KNOX","reg=civilian,family,worker|tmp=seasoned,veteran|st=friendly,neutral|world=fence",{"Fort Knox is a big fence with men behind it who don't know you - treat it like that"}},
{"ASK_FORT_KNOX","reg=civilian,family,worker,rescue|st=careful|world=fence",{"I don't talk about the base with strangers, too many rifles on both sides of that fence"}},
{"ASK_FORT_KNOX","reg=civilian,family,worker,rescue|st=hostile",{"Go knock on the gate and see what they do to you"}},
{"ASK_FORT_KNOX","reg=worker|st=friendly,neutral|world=road",{"Did contract painting on post three summers, I know the back roads in - I also know there's a man watching every one of them"}},
{"ASK_FORT_KNOX","reg=rescue|st=friendly,neutral",{"The Army hospital on post quit taking our transfers after Saturday - I don't blame them, and I do"}},
{"ASK_FORT_KNOX","reg=law,swat|st=friendly,neutral",{"Base went to full lockdown the first night - MPs stopped answering our landline by morning"}},
{"ASK_FORT_KNOX","reg=law|st=friendly,neutral",{"Fort Knox is federal ground, {sir}, they didn't listen to the county before, and they sure don't now"}},
{"ASK_FORT_KNOX","reg=law,swat|st=careful,hostile",{"You're not going anywhere near the base, and you're not coming any closer to me"}},
{"ASK_FORT_KNOX","reg=military|tmp=seasoned,veteran|st=friendly,neutral",{"Post is still manned - Perimeter's hot - don't approach without a white flag and a good reason"}},
{"ASK_FORT_KNOX","reg=military|st=friendly,neutral|day=5,9999",{"I'm from Knox - was, they sealed the gates with my squad on the wrong side"}},
{"ASK_FORT_KNOX","reg=military|role=soldier_green|st=friendly,neutral",{"I did basic there, graduated three weeks before all this - Mama drove up for the ceremony"}},
{"ASK_FORT_KNOX","reg=elite",{"Installation status is not for release"}},
{"ASK_FORT_KNOX","reg=military|st=careful,hostile",{"What's your interest in the base? Answer from right there"}},
{"ASK_FORT_KNOX","reg=outlaw,raider,crime|st=friendly,neutral",{"Gold's still in the vault, probably, nobody left to spend it on - funny how that works out"}},
{"ASK_FORT_KNOX","reg=prison|st=friendly,neutral",{"Army's got its own stockade on post, glad I wasn't in that one - they didn't leave theirs open"}},
{"ASK_FORT_KNOX","reg=gang|st=friendly,neutral",{"Forget the gold, {g:man|lady}, I want whatever's in the armory"}},
{"ASK_FORT_KNOX","reg=club|st=friendly,neutral|world=road",{"Rode past the base on 31W, tanks on the grass with the barrels on the road - we didn't stop for pictures"}},
{"ASK_FORT_KNOX","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"Base won't save you, we're a lot closer than it is"}},
{"ASK_FORT_KNOX","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"Think the Army's gonna hear you from here? Go ahead and yell"}},
{"ASK_FORT_KNOX","reg=civilian|tmp=fresh|st=friendly,neutral",{"The base? I figured that'd be the safest place in America - figured wrong, I guess"}},
{"ASK_FORT_KNOX","reg=family|st=neutral|mood=sad",{"My cousin's stationed there - was, I don't know how to finish that sentence"}},
{"ASK_FORT_KNOX","reg=worker|tmp=seasoned|st=neutral",{"Half this county worked out there one way or another - now nobody's in or out"}},
{"ASK_FORT_KNOX","role=rescue_medical|st=neutral",{"Their hospital's the biggest thing around here, they sealed it on the seventh"}},
{"ASK_FORT_KNOX","role=rescue_clergy|st=neutral",{"Folks keep walking toward that gate like it's a church - it ain't a church"}},
{"ASK_FORT_KNOX","reg=civilian|tmp=seasoned|st=neutral",{"Everybody's plan is get to the base, the base has a plan too and we ain't in it"}},
{"ASK_FORT_KNOX","role=law_deputy|st=neutral|world=cars",{"MPs turned back a line of cars at the gate on the sixth - polite, then not polite"}},
{"ASK_FORT_KNOX","role=law_sheriff|st=neutral",{"That base has been our neighbor sixty years, now it's another country entirely"}},
{"ASK_FORT_KNOX","role=soldier_nco|tmp=veteran|st=neutral",{"It's a post, not a fortress, folks think gold vault and forget it's mostly offices"}},
{"ASK_FORT_KNOX","role=soldier_green|tmp=fresh|st=neutral|mood=sad",{"I trained there in the spring, I keep thinking if I could just get back to that gate"}},
{"ASK_FORT_KNOX","role=elite_delta|tmp=veteran|st=neutral|world=building",{"Anything that mattered there went out early, what's left is a wall and tired people"}},
{"ASK_FORT_KNOX","role=deserter|st=careful|hour=16,5",{"Don't walk up on that gate after dark, I'll leave it right there"}},
{"ASK_FORT_KNOX","reg=club,crime|st=neutral|mood=funny",{"All my life that gold was the thing nobody could get at - now it's the least guarded"}},
{"ASK_FORT_KNOX","reg=raider,gang|tmp=predator|st=hostile",{"Gold, people still talk about the gold - you can't eat gold and you can't shoot it"}},
{"ASK_GOD","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Believe in God? I did, I do, I don't know, ask me tomorrow, ask me when I've slept","I prayed every night, still do, even mad at Him... maybe because I'm mad at Him","I don't think this is punishment, I think it's just, it's just an awful thing that happened to us","God doesn't do this, people do, or maybe nature, but not God, I can't believe it","I used to go to church every Sunday -- now I just sit on the floor and talk to the ceiling","If God's out there, He's got a lot to answer for"}},
{"ASK_GOD","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"I've buried too many to believe, but not enough to stop praying","Some nights my faith burns bright, some nights the batteries are dead, but I keep carrying it","I don't pray anymore, I just do the next right thing, it's close enough","Punishment? maybe, we've been cruel to each other for a long time"}},
{"ASK_GOD","reg=civilian,family,worker,rescue|st=careful",{"That's a personal question!!","Keep your religion to yourself","Don't ask me about God","That's between me and Him","What I believe is my business - why are you asking?"},false,{[5]="GENERIC"}},
{"ASK_GOD","role=rescue_clergy",{"I do believe -- and I also doubt, both are true, and God can handle both..","God didn't do this... I believe that with all my heart, and He's in it with us","I prayed for answers... and I got silence, but silence isn't absence, sometimes it's just listening.."}},
{"ASK_GOD","role=rescue_medical",{"I've seen what happens to a body, and I've seen the soul leave one, and I can't tell you there's nothing there"}},
{"ASK_GOD","role=militia",{"God's on every side of every war, I stick to the part I can control"}},
{"ASK_GOD","reg=civilian,family,worker,rescue|st=friendly,neutral",{"I pray, but I can't say if anybody listens","I used to be sure","My mother said God doesn't give you more than you can handle","I talk to Him","I believe, but I'm angry about it","I don't go to church anymore","The faith I have is small","I think He's weeping","I won't say it's punishment","I prayed for a sign"},false,false,{[1]={{t="I pray anyway...",afterMs=3500},{t="it's a good habit",afterMs=3000}},[2]={{t="now I'm just hoping",afterMs=3200},{t="hoping counts, I think",afterMs=2800}},[3]={{t="I told her she's got Him mixed up with the electric company",afterMs=3500}},[4]={{t="mostly yell",afterMs=3200},{t="He hasn't answered, but He hasn't hung up",afterMs=2800}},[5]={{t="both can be true",afterMs=3500}},[6]={{t="I carry it with me instead",afterMs=3200}},[7]={{t="the size of a mustard seed, as they say",afterMs=3500},{t="and about as dry",afterMs=3000}},[8]={{t="but I'm not sure whether I'm projecting",afterMs=3500}},[9]={{t="we did this to ourselves, or somebody did",afterMs=3200}},[10]={{t="and got a sparrow",afterMs=3500},{t="I'm taking it",afterMs=3000}}}},
{"ASK_GOD","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"God and I are on speaking terms","I figure if there's a God, He's got a sense of humor, heh"},false,false,{[1]={{t="mostly me speaking, Him ignoring",afterMs=3200}},[2]={{t="He made me, after all",afterMs=3500}}}},
{"ASK_GOD","reg=civilian,family,worker,rescue|st=friendly",{"Pray with me, if you like"},false,false,{[1]={{t="it's easier with two",afterMs=3200}}}},
{"ASK_GOD","reg=raider|st=neutral,careful",{"God? He took a vacation, and I don't blame him, he saw what was coming","Maybe He's punishing us, but if so, I'm having a damn good time","I don't pray, I plan, and my plans work better than prayers","The preacher at my mother's church said this was the end times, and I laughed, but I'm not laughing now","There's no God, pal, only guns and luck"}},
{"ASK_GOD","reg=raider|st=hostile",{"Don't preach to me, I'll put you in the ground right now!"}},
{"ASK_GOD","reg=raider|st=friendly",{"I pray every night, honestly, I know I shouldn't, I've done terrible things, but I do","My grandmother said God watches over fools and drunks, I qualify for both"}},
{"ASK_GOD","reg=gang|st=neutral,careful",{"God left this neighborhood a long time ago, I don't expect Him back","My mama prays every day, and I tell her it don't do nothing","I ain't saying there's no God, I'm saying He's got a lot of explaining to do","If there is a God, He's watching and doing nothing, which is worse than not being there"}},
{"ASK_GOD","reg=gang|st=hostile",{"Don't talk to me about God, my homeboys are dead because of Him!"}},
{"ASK_GOD","reg=gang|st=friendly",{"I pray, {g:man|lady}, I'm not ashamed, I pray for my people every night"}},
{"ASK_GOD","reg=club|st=neutral,careful",{"I'm a sinner, I know it, but I still pray, can't hurt","The Lord works in mysterious ways, but this is a little much, even for Him","Our chaplain read from Revelation, it was a little too on the nose"}},
{"ASK_GOD","reg=club|st=hostile",{"God's got nothing to do with this, it's men and what they do"}},
{"ASK_GOD","reg=club|st=friendly",{"I pray, {g:brother|sister}, I pray more than I ever did, and it helps"}},
{"ASK_GOD","reg=crime|st=neutral,careful",{"Faith is a private matter, I keep mine to myself","I believe in outcomes, God or no God","I was raised Catholic, and some of it stuck"}},
{"ASK_GOD","reg=crime|st=friendly",{"I have prayed, yes, though I doubt He's listening to me in particular"}},
{"ASK_GOD","reg=prison|st=neutral,careful",{"I found Jesus in prison, then lost Him again when the lights went out","I pray, but I think He's busy","In lockup I prayed all the time, for nothing, nobody answered, now it's worse"}},
{"ASK_GOD","reg=prison|st=hostile",{"Don't preach to me, I've heard it all!"}},
{"ASK_GOD","reg=prison|st=friendly",{"I pray every night, please let me wake up, please let me be free, please let me be forgiven"}},
{"ASK_GOD","reg=outlaw|st=neutral,careful",{"I figure He's up there, just taking a long coffee break","Raised Baptist, still believe, though I don't go to church anymore","The woods taught me more about God than any church ever did"}},
{"ASK_GOD","reg=outlaw|st=friendly",{"Honestly? I talk to Him out loud when no one's around, just in case"}},
{"ASK_GOD","role=deserter|st=neutral,careful",{"I've asked God for forgiveness every night, so far He hasn't answered"}},
{"ASK_GOD","reg=law|st=neutral,careful",{"I've seen things that shook my faith, and I've seen things that restored it, just not lately","Chaplain at the department used to say God doesn't give us more than we can bear, I'd like to have a word with him","I pray before every shift, still do"}},
{"ASK_GOD","reg=law|st=hostile",{"My faith is my business, and I'd thank you to respect that"}},
{"ASK_GOD","reg=law|st=friendly",{"I pray for everyone I can't save, it's a long list"}},
{"ASK_GOD","role=law_sheriff|st=neutral,careful",{"I go to the same church I've gone to my whole life, and I sit in the same pew, even when it's empty"}},
{"ASK_GOD","reg=military|st=neutral,careful",{"Chaplain's gone, but I still say a prayer at night","I'm not a religious man, but I find myself praying more than I used to","God and country, that's what they taught us, but one of them isn't answering"}},
{"ASK_GOD","reg=military|st=hostile",{"Religion is not a topic I'll discuss with civilians"}},
{"ASK_GOD","reg=military|st=friendly",{"I pray for my family, and for you, too"}},
{"ASK_GOD","role=soldier_nco|st=neutral,careful",{"God doesn't care about this war, soldier, but I'd keep praying anyway"}},
{"ASK_GOD","role=soldier_green|st=neutral,careful",{"I pray all the time now... please God, please just let me go home, please"}},
{"ASK_GOD","reg=elite|st=neutral,careful",{"Nobody on my team prays out loud"}},
{"ASK_GOD","role=mercenary|st=neutral,careful",{"I've seen God in a lot of foreign places, none of them were pretty"}},
{"ASK_GOD","role=militia|st=neutral,careful",{"Church has been our anchor since this began, we sing every Sunday, loud as we can","Pastor Ellis says this is a test, and the Lord is watching to see who helps their neighbor","I don't question God, but I sure do question what He's thinking"}},
{"ASK_GOD","role=militia|st=friendly",{"We pray every night as a family, and it helps, it really does"}},
{"ASK_GOD","reg=civilian,family|tmp=fresh|st=friendly,neutral",{"I pray every night, lately I just list names, I figure He knows the rest","My mother would say this is Revelation, I hope she's wrong, I think she'd hope so too","Yes, I have to, if I don't, then all of this is just, it's just this"}},
{"ASK_GOD","reg=civilian,family|role=family_woman,civilian_woman|tmp=fresh|st=friendly,neutral",{"I used to, I asked Him to spare my husband and He didn't - so we're not talking right now, Him and me"}},
{"ASK_GOD","reg=civilian,family|tmp=seasoned|st=friendly,neutral",{"I offered Him the farm, my good shotgun and ten years off the end - guess the line was busy","Believe in Him, sure - trust Him? We're working on it, me and Him"}},
{"ASK_GOD","reg=civilian,family,worker,rescue|st=hostile",{"God's not here, friend - just me, and I'm not the forgiving one"}},
{"ASK_GOD","reg=rescue|role=rescue_clergy|st=friendly,neutral|world=road",{"I held a service in the Baptist church parking lot on Sunday - seven people came - seven's a good number"}},
{"ASK_GOD","reg=rescue|role=rescue_clergy|st=friendly,neutral",{"Punishment? No - God doesn't bite people, folks will blame Him anyway, and I'll sit with them when they do"}},
{"ASK_GOD","reg=rescue|role=rescue_medical,rescue_firefighter|st=friendly,neutral|world=cars",{"Seen too many wrecks on the interstate to be sure of much - but I say a little something when I close their eyes"}},
{"ASK_GOD","reg=worker|st=friendly,neutral",{"Grandpa said God works like a second shift, somebody's always on, you just don't see 'em, I hope that's so"}},
{"ASK_GOD","reg=law,swat|st=friendly,neutral",{"I'm a Methodist, I pray before every shift, lately it's a longer prayer","I believe in God and a twelve-gauge, which one comes first depends on the day"}},
{"ASK_GOD","reg=law,swat|st=careful,hostile",{"Say your prayers from where you are, don't come closer"}},
{"ASK_GOD","reg=military|tmp=fresh|st=friendly,neutral",{"My grandma sewed a little cross into my duffel, I touch it before every patrol - is that stupid?"},false,{[1]="GENERIC"}},
{"ASK_GOD","reg=military,elite|tmp=seasoned,veteran|st=friendly,neutral",{"Folks say you won't find an atheist in a foxhole - I've served with some, good soldiers, both kinds"}},
{"ASK_GOD","reg=elite|st=friendly,neutral",{"Faith, sure... and a clean weapon never hurt either"}},
{"ASK_GOD","reg=military,elite|st=careful,hostile",{"Pray on the move, you can't stay here"}},
{"ASK_GOD","reg=outlaw,crime|st=friendly,neutral",{"Grew up in a tent revival family, handled snakes at nine years old, then one bit me - so","Punishment? If God wanted to punish Knox County, He'd have started with me - I'm still here, so"}},
{"ASK_GOD","reg=raider,gang,club|st=friendly,neutral",{"God? Hahaha - God clocked out, {g:man|lady}, I'm running the place now"}},
{"ASK_GOD","reg=prison|st=friendly,neutral|world=door",{"Prayed plenty in the pen - nobody answered, then the cell doors came open on their own - make of that what you want"}},
{"ASK_GOD","reg=outlaw,raider,gang,club,crime,prison|st=careful",{"Preaching at me? I got my own church, and you ain't a member"}},
{"ASK_GOD","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"You'll be meeting Him soon enough - ask Him yourself"}},
{"ASK_GOD","reg=civilian|tmp=fresh|st=friendly,neutral",{"I prayed on the sixth, I don't know what I was asking for - just less of it"}},
{"ASK_GOD","reg=family|st=neutral,friendly",{"We say grace over canned corn, feels stupid and we do it anyway"}},
{"ASK_GOD","reg=worker|tmp=seasoned|st=neutral",{"I believe in Him, I'd just like a word with Him about the scheduling"}},
{"ASK_GOD","role=rescue_medical|st=neutral",{"I've seen too much plain bad luck to call any of it a plan"}},
{"ASK_GOD","role=rescue_clergy|st=friendly,neutral",{"Folks keep asking if He did this, I tell 'em I'd ask Him the same question"}},
{"ASK_GOD","role=rescue_firefighter|st=neutral|world=door",{"I pray at doors, not out loud, just before I go through one"}},
{"ASK_GOD","reg=civilian|tmp=seasoned|st=neutral,friendly",{"Raised Baptist, still Baptist enough to feel bad about not going"}},
{"ASK_GOD","role=family_elder|st=friendly,neutral",{"I've said the same prayer every night since 1941, I ain't changing it now"}},
{"ASK_GOD","role=law_deputy|st=neutral|mood=grim",{"I say the words at funerals, said 'em nine times this month"}},
{"ASK_GOD","role=soldier_nco|tmp=veteran|st=neutral",{"There's no atheists in a ditch, that's an old line and it's mostly true"}},
{"ASK_GOD","role=soldier_green|tmp=fresh|st=neutral",{"Got a cross my grandma gave me, my hand's been on it since the fifth"}},
{"ASK_GOD","role=elite_delta|tmp=veteran|st=neutral",{"I don't discuss it, that ain't a no"}},
{"ASK_GOD","reg=club|st=neutral",{"God and me have an understanding, he leaves me be, I don't complain loud"}},
{"ASK_GOD","role=crime_member|st=neutral",{"I'd say something clever, but my mother would hear it somehow - no comment"}},
{"ASK_GOD","reg=raider,prison|tmp=predator|st=hostile",{"If He's watching, He's had a hundred chances to stop me - ain't taken one yet"}},
{"ASK_GOD","reg=civilian,family|tmp=fresh|st=hostile",{"I quit on the ninth, that's between me and Him and it ain't your business"}},
{"ASK_GOT_COLD","",{"No, I'm alright - why, do I sound bad?","Not a sniffle, knock on wood","Sniffling, mostly. Keep a little distance","Nope, healthy as a horse","If I had, I wouldn't tell you - no offense"}},
{"ASK_GOT_COLD","reg=civilian,family,worker,rescue|tmp=fresh",{"Don't ask that, nobody wants to hear it, in this world"}},
{"ASK_GOT_COLD","reg=civilian,family,worker,rescue|tmp=seasoned",{"Only the kind in my head - Lack of sleep"}},
{"ASK_GOT_COLD","reg=civilian,family,worker,rescue",{"Cough drops and a good coat, that's my secret"}},
{"ASK_GOT_COLD","reg=law,swat",{"Doing fine, now if I could just find a clean pair of socks"}},
{"ASK_GOT_COLD","reg=military,elite",{"Medically fit - next question"}},
