{"ASK_GOT_COLD","reg=prison|st=neutral,careful",{"I-- no, I'm not sick, I'm fine, I promise"}},
{"ASK_GOT_COLD","reg=outlaw|st=neutral,careful",{"A touch of something, friend, it'll pass"}},
{"ASK_GOT_COLD","reg=law|st=neutral,careful",{"A minor cold, nothing to worry about"}},
{"ASK_GOT_COLD","reg=military|st=neutral,careful",{"A common cold, medic is aware"}},
